static const char ab_glsl_crt_pi[] =
  "/*\n"
  "    crt-pi - A Raspberry Pi friendly CRT shader.\n"
  "\n"
  "    Copyright (C) 2015-2016 davej\n"
  "\n"
  "    This program is free software; you can redistribute it and/or modify it\n"
  "    under the terms of the GNU General Public License as published by the Free\n"
  "    Software Foundation; either version 2 of the License, or (at your option)\n"
  "    any later version.\n"
  "\n"
  "\n"
  "Notes:\n"
  "\n"
  "This shader is designed to work well on Raspberry Pi GPUs (i.e. 1080P @ 60Hz on a game with a 4:3 aspect ratio). It pushes the Pi's GPU hard and enabling some features will slow it down so that it is no longer able to match 1080P @ 60Hz. You will need to overclock your Pi to the fastest setting in raspi-config to get the best results from this shader: 'Pi2' for Pi2 and 'Turbo' for original Pi and Pi Zero. Note: Pi2s are slower at running the shader than other Pis, this seems to be down to Pi2s lower maximum memory speed. Pi2s don't quite manage 1080P @ 60Hz - they drop about 1 in 1000 frames. You probably won't notice this, but if you do, try enabling FAKE_GAMMA.\n"
  "\n"
  "SCANLINES enables scanlines. You'll almost certainly want to use it with MULTISAMPLE to reduce moire effects. SCANLINE_WEIGHT defines how wide scanlines are (it is an inverse value so a higher number = thinner lines). SCANLINE_GAP_BRIGHTNESS defines how dark the gaps between the scan lines are. Darker gaps between scan lines make moire effects more likely.\n"
  "\n"
  "GAMMA enables gamma correction using the values in INPUT_GAMMA and OUTPUT_GAMMA. FAKE_GAMMA causes it to ignore the values in INPUT_GAMMA and OUTPUT_GAMMA and approximate gamma correction in a way which is faster than true gamma whilst still looking better than having none. You must have GAMMA defined to enable FAKE_GAMMA.\n"
  "\n"
  "CURVATURE distorts the screen by CURVATURE_X and CURVATURE_Y. Curvature slows things down a lot.\n"
  "\n"
  "By default the shader uses linear blending horizontally. If you find this too blury, enable SHARPER.\n"
  "\n"
  "BLOOM_FACTOR controls the increase in width for bright scanlines.\n"
  "\n"
  "MASK_TYPE defines what, if any, shadow mask to use. MASK_BRIGHTNESS defines how much the mask type darkens the screen.\n"
  "\n"
  "*/\n"
  "\n"
  "#pragma parameter CURVATURE_X \"Screen curvature - horizontal\" 0.10 0.0 1.0 0.01\n"
  "#pragma parameter CURVATURE_Y \"Screen curvature - vertical\" 0.15 0.0 1.0 0.01\n"
  "#pragma parameter MASK_BRIGHTNESS \"Mask brightness\" 0.70 0.0 1.0 0.01\n"
  "#pragma parameter SCANLINE_WEIGHT \"Scanline weight\" 6.0 0.0 15.0 0.1\n"
  "#pragma parameter SCANLINE_GAP_BRIGHTNESS \"Scanline gap brightness\" 0.12 0.0 1.0 0.01\n"
  "#pragma parameter BLOOM_FACTOR \"Bloom factor\" 1.5 0.0 5.0 0.01\n"
  "#pragma parameter INPUT_GAMMA \"Input gamma\" 2.4 0.0 5.0 0.01\n"
  "#pragma parameter OUTPUT_GAMMA \"Output gamma\" 2.2 0.0 5.0 0.01\n"
  "\n"
  "// Haven't put these as parameters as it would slow the code down.\n"
  "#define SCANLINES\n"
  "#define MULTISAMPLE\n"
  "#define GAMMA\n"
  "//#define FAKE_GAMMA\n"
  "//#define CURVATURE\n"
  "//#define SHARPER\n"
  "// MASK_TYPE: 0 = none, 1 = green/magenta, 2 = trinitron(ish)\n"
  "#define MASK_TYPE 1\n"
  "\n"
  "\n"
  "#ifdef GL_ES\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "precision highp float;\n"
  "#else\n"
  "precision mediump float;\n"
  "#endif\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "#define COMPAT_PRECISION highp\n"
  "#else \n"
  "#define COMPAT_PRECISION mediump\n"
  "#endif\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "#ifdef PARAMETER_UNIFORM\n"
  "uniform COMPAT_PRECISION float CURVATURE_X;\n"
  "uniform COMPAT_PRECISION float CURVATURE_Y;\n"
  "uniform COMPAT_PRECISION float MASK_BRIGHTNESS;\n"
  "uniform COMPAT_PRECISION float SCANLINE_WEIGHT;\n"
  "uniform COMPAT_PRECISION float SCANLINE_GAP_BRIGHTNESS;\n"
  "uniform COMPAT_PRECISION float BLOOM_FACTOR;\n"
  "uniform COMPAT_PRECISION float INPUT_GAMMA;\n"
  "uniform COMPAT_PRECISION float OUTPUT_GAMMA;\n"
  "#else\n"
  "#define CURVATURE_X 0.10\n"
  "#define CURVATURE_Y 0.25\n"
  "#define MASK_BRIGHTNESS 0.70\n"
  "#define SCANLINE_WEIGHT 6.0\n"
  "#define SCANLINE_GAP_BRIGHTNESS 0.12\n"
  "#define BLOOM_FACTOR 1.5\n"
  "#define INPUT_GAMMA 2.4\n"
  "#define OUTPUT_GAMMA 2.2\n"
  "#endif\n"
  "\n"
  "/* COMPATIBILITY\n"
  "   - GLSL compilers\n"
  "*/\n"
  "\n"
  "uniform vec2 TextureSize;\n"
  "#if defined(CURVATURE)\n"
  "varying vec2 screenScale;\n"
  "#endif\n"
  "varying vec2 TEX0;\n"
  "varying float filterWidth;\n"
  "varying float soft;\n"
  "\n"
  "#if defined(VERTEX)\n"
  "uniform mat4 MVPMatrix;\n"
  "attribute vec4 VertexCoord;\n"
  "attribute vec2 TexCoord;\n"
  "uniform vec2 InputSize;\n"
  "uniform vec2 OutputSize;\n"
  "\n"
  "void main()\n"
  "{\n"
  "#if defined(CURVATURE)\n"
  "    screenScale = TextureSize / InputSize;\n"
  "#endif\n"
  "    filterWidth = (InputSize.y / OutputSize.y) / 3.0;\n"
  "    // AutoBleem: how far a line's height on the screen is from a whole number of pixels - 0 at 720p (3 px)\n"
  "    // or 4K (9 px), 1 at 1080p (4.5 px); where it is above 0 the gaps are lighter and the beam wider, so\n"
  "    // lines of 4 and 5 pixels do not show as a pattern (dark gaps make moire likelier, as said above); a\n"
  "    // whole scale draws as before\n"
  "    soft = 1.0 - abs(2.0 * fract(OutputSize.y / InputSize.y) - 1.0);\n"
  "    TEX0 = TexCoord;\n"
  "    gl_Position = MVPMatrix * VertexCoord;\n"
  "}\n"
  "#elif defined(FRAGMENT)\n"
  "\n"
  "uniform sampler2D Texture;\n"
  "\n"
  "#if defined(CURVATURE)\n"
  "vec2 Distort(vec2 coord)\n"
  "{\n"
  "    vec2 CURVATURE_DISTORTION = vec2(CURVATURE_X, CURVATURE_Y);\n"
  "    // Barrel distortion shrinks the display area a bit, this will allow us to counteract that.\n"
  "    vec2 barrelScale = 1.0 - (0.23 * CURVATURE_DISTORTION);\n"
  "    coord *= screenScale;\n"
  "    coord -= vec2(0.5);\n"
  "    float rsq = coord.x * coord.x + coord.y * coord.y;\n"
  "    coord += coord * (CURVATURE_DISTORTION * rsq);\n"
  "    coord *= barrelScale;\n"
  "    if (abs(coord.x) >= 0.5 || abs(coord.y) >= 0.5)\n"
  "        coord = vec2(-1.0);        // If out of bounds, return an invalid value.\n"
  "    else\n"
  "    {\n"
  "        coord += vec2(0.5);\n"
  "        coord /= screenScale;\n"
  "    }\n"
  "\n"
  "    return coord;\n"
  "}\n"
  "#endif\n"
  "\n"
  "float CalcScanLineWeight(float dist)\n"
  "{\n"
  "    return max(1.0-dist*dist*SCANLINE_WEIGHT*(1.0 - 0.35*soft), mix(SCANLINE_GAP_BRIGHTNESS, 0.30, soft));\n"
  "}\n"
  "\n"
  "float CalcScanLine(float dy)\n"
  "{\n"
  "    float scanLineWeight = CalcScanLineWeight(dy);\n"
  "#if defined(MULTISAMPLE)\n"
  "    scanLineWeight += CalcScanLineWeight(dy-filterWidth);\n"
  "    scanLineWeight += CalcScanLineWeight(dy+filterWidth);\n"
  "    scanLineWeight *= 0.3333333;\n"
  "#endif\n"
  "    return scanLineWeight;\n"
  "}\n"
  "\n"
  "void main()\n"
  "{\n"
  "#if defined(CURVATURE)\n"
  "    vec2 texcoord = Distort(TEX0);\n"
  "    if (texcoord.x < 0.0)\n"
  "        gl_FragColor = vec4(0.0);\n"
  "    else\n"
  "#else\n"
  "    vec2 texcoord = TEX0;\n"
  "#endif\n"
  "    {\n"
  "        vec2 texcoordInPixels = texcoord * TextureSize;\n"
  "#if defined(SHARPER)\n"
  "        vec2 tempCoord = floor(texcoordInPixels) + 0.5;\n"
  "        vec2 coord = tempCoord / TextureSize;\n"
  "        vec2 deltas = texcoordInPixels - tempCoord;\n"
  "        float scanLineWeight = CalcScanLine(deltas.y);\n"
  "        vec2 signs = sign(deltas);\n"
  "        deltas.x *= 2.0;\n"
  "        deltas = deltas * deltas;\n"
  "        deltas.y = deltas.y * deltas.y;\n"
  "        deltas.x *= 0.5;\n"
  "        deltas.y *= 8.0;\n"
  "        deltas /= TextureSize;\n"
  "        deltas *= signs;\n"
  "        vec2 tc = coord + deltas;\n"
  "#else\n"
  "        float tempY = floor(texcoordInPixels.y) + 0.5;\n"
  "        float yCoord = tempY / TextureSize.y;\n"
  "        float dy = texcoordInPixels.y - tempY;\n"
  "        float scanLineWeight = CalcScanLine(dy);\n"
  "        float signY = sign(dy);\n"
  "        dy = dy * dy;\n"
  "        dy = dy * dy;\n"
  "        dy *= 8.0;\n"
  "        dy /= TextureSize.y;\n"
  "        dy *= signY;\n"
  "        vec2 tc = vec2(texcoord.x, yCoord + dy);\n"
  "#endif\n"
  "\n"
  "        vec3 colour = texture2D(Texture, tc).rgb;\n"
  "\n"
  "#if defined(SCANLINES)\n"
  "#if defined(GAMMA)\n"
  "#if defined(FAKE_GAMMA)\n"
  "        colour = colour * colour;\n"
  "#else\n"
  "        colour = pow(colour, vec3(INPUT_GAMMA));\n"
  "#endif\n"
  "#endif\n"
  "        scanLineWeight *= BLOOM_FACTOR;\n"
  "        colour *= scanLineWeight;\n"
  "\n"
  "#if defined(GAMMA)\n"
  "#if defined(FAKE_GAMMA)\n"
  "        colour = sqrt(colour);\n"
  "#else\n"
  "        colour = pow(colour, vec3(1.0/OUTPUT_GAMMA));\n"
  "#endif\n"
  "#endif\n"
  "#endif\n"
  "#if MASK_TYPE == 0\n"
  "        gl_FragColor = vec4(colour, 1.0);\n"
  "#else\n"
  "#if MASK_TYPE == 1\n"
  "        float whichMask = fract(gl_FragCoord.x * 0.5);\n"
  "        vec3 mask;\n"
  "        if (whichMask < 0.5)\n"
  "            mask = vec3(MASK_BRIGHTNESS, 1.0, MASK_BRIGHTNESS);\n"
  "        else\n"
  "            mask = vec3(1.0, MASK_BRIGHTNESS, 1.0);\n"
  "#elif MASK_TYPE == 2\n"
  "        float whichMask = fract(gl_FragCoord.x * 0.3333333);\n"
  "        vec3 mask = vec3(MASK_BRIGHTNESS, MASK_BRIGHTNESS, MASK_BRIGHTNESS);\n"
  "        if (whichMask < 0.3333333)\n"
  "            mask.x = 1.0;\n"
  "        else if (whichMask < 0.6666666)\n"
  "            mask.y = 1.0;\n"
  "        else\n"
  "            mask.z = 1.0;\n"
  "#endif\n"
  "\n"
  "        gl_FragColor = vec4(colour * mask, 1.0);\n"
  "#endif\n"
  "    }\n"
  "}\n"
  "#endif\n"
  "\n";

static const char ab_glsl_crt_raster[] =
  "/*\n"
  "    crt-raster - AutoBleem's CRT filter: a tube's beam and its phosphor mask drawn at the screen's own\n"
  "    resolution, not the game's.\n"
  "\n"
  "    (C) AutoBleem team, 2026\n"
  "\n"
  "    This work is licensed under the terms of the GNU GPLv2 or later.\n"
  "    See the COPYING file in the top-level directory.\n"
  "\n"
  "A tube has no pixels: the beam sweeps one line of the picture at a time, as a soft spot whose height grows\n"
  "with its brightness, and what lights up is the phosphor's RGB raster - the same on the glass whatever the\n"
  "game drew. So the two things are drawn separately here:\n"
  "\n"
  "- the beam, per line of the PlayStation's picture (TextureSize is its own line count - libpicofe's\n"
  "  plat_ab_set_filter_picture): a Gaussian of the line's colour around its centre, from the two lines the\n"
  "  pixel lies between. Each line's energy is kept (the Gaussian's area is 1 whatever its width), so the\n"
  "  picture is as bright as without the filter and only the light is redistributed: a dark line is a thin\n"
  "  spot with a dark gap beside it, a bright one widens and fills the gap. The Gaussian is widened by the\n"
  "  pixel's own height (a box's variance, h*h/12), which is what sampling it once per pixel needs to keep\n"
  "  lines of 4 and 5 pixels (1080p's 4.5) even. Across, the line is read with the hardware's bilinear\n"
  "  filter, its ramp squeezed between the PlayStation's pixels (SHARPNESS) - two reads a pixel in all.\n"
  "- the mask, per pixel of the screen (gl_FragCoord): CRT_MASK picks the raster (0 aperture grille,\n"
  "  1 slot mask, 2 delta, 3 none); its period is 3 screen pixels from 900 lines up, 2 below (720p, where a\n"
  "  triad does not fit: green and magenta), 6 from 1600 up. The lit and dark levels are chosen so the mask\n"
  "  averages 1 - the picture keeps its brightness, only white clips. With CRT_MASK_TEXTURE (GLES 3) the host\n"
  "  draws it once into a pattern the mask repeats in (MaskTexture, MaskSize - ab_shaders.c) and each pixel\n"
  "  reads it back.\n"
  "\n"
  "Both in linear light (INPUT_GAMMA / OUTPUT_GAMMA). This pass draws only the picture's own rectangle: the\n"
  "screen halo's bands are drawn from it averaged 16 x 16 (libpicofe's glow pass), where a 2-3 pixel mask is\n"
  "gone, so they carry no mask.\n"
  "*/\n"
  "\n"
  "#ifndef CRT_MASK\n"
  "#define CRT_MASK 0\n"
  "#endif\n"
  "\n"
  "#define SIGMA_DARK   0.27   /* the beam's half-height (Gaussian sigma) in lines: a black line */\n"
  "#define SIGMA_BRIGHT 0.42   /* ... and a white one */\n"
  "#define SHARPNESS    1.6    /* across: 1 = plain bilinear, more = a shorter ramp between pixels */\n"
  "#define MASK_DARK    0.70   /* a phosphor stripe of another colour; the lit one is set from it */\n"
  "#define INPUT_GAMMA  2.4\n"
  "#define OUTPUT_GAMMA 2.2\n"
  "#define SIGMA_LITE   0.36   /* CRT_LITE: one beam height for every colour, between the dark and the bright one */\n"
  "\n"
  "/*\n"
  "Two lighter builds of the same picture for a weak GPU (the PSC's PowerVR fell under 40 fps in Tekken 3 at\n"
  "720p with the full one), chosen by the host with a define, as CRT_MASK is:\n"
  "- CRT_FAST_GAMMA: gamma 2.0 - a square in and a square root out instead of nine pow() a pixel - and the\n"
  "  colour maths in mediump, which that GPU runs at twice the rate (the coordinates stay highp: a 640 pixel\n"
  "  line needs more than mediump's 10 bits for its fractions).\n"
  "- CRT_LITE (implies the above): the beam's height no longer follows the colour, so its shape is the same\n"
  "  for every pixel of the draw: a smooth bump (1 - x^2)^2 of the Gaussian's variance and area 1, whose width\n"
  "  and scale the vertex shader works out once - no exp() and no inversesqrt() per pixel.\n"
  "*/\n"
  "#ifdef CRT_LITE\n"
  "#define CRT_FAST_GAMMA\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "precision highp float;\n"
  "#else\n"
  "precision mediump float;\n"
  "#endif\n"
  "#endif\n"
  "\n"
  "#if defined(GL_ES) && defined(CRT_FAST_GAMMA)\n"
  "#define COLOR mediump vec3\n"
  "#else\n"
  "#define COLOR vec3\n"
  "#endif\n"
  "\n"
  "uniform vec2 TextureSize;\n"
  "uniform vec2 OutputSize;\n"
  "varying vec2 uv;\n"
  "varying float boxVar;\n"
  "#ifdef CRT_LITE\n"
  "varying float bumpInvW;    /* 1 / the bump's half-width, in lines */\n"
  "varying float bumpScale;    /* its peak, so that its area is 1 */\n"
  "#endif\n"
  "\n"
  "#if defined(VERTEX)\n"
  "uniform mat4 MVPMatrix;\n"
  "attribute vec4 VertexCoord;\n"
  "attribute vec4 TexCoord;\n"
  "\n"
  "void main()\n"
  "{\n"
  "    float h = TextureSize.y / OutputSize.y;    /* a screen pixel's height in lines */\n"
  "    boxVar = h * h / 12.0;\n"
  "#ifdef CRT_LITE\n"
  "    /* (1 - (x/w)^2)^2 has the variance w^2/7 and the area 16w/15 */\n"
  "    float w = sqrt(7.0 * (SIGMA_LITE * SIGMA_LITE + boxVar));\n"
  "    bumpInvW = 1.0 / w;\n"
  "    bumpScale = 15.0 / (16.0 * w);\n"
  "#endif\n"
  "    uv = TexCoord.xy;\n"
  "    gl_Position = MVPMatrix * VertexCoord;\n"
  "}\n"
  "#elif defined(FRAGMENT)\n"
  "\n"
  "uniform sampler2D Texture;\n"
  "\n"
  "#ifdef CRT_LITE\n"
  "/* a line's light at dy lines from its centre: the bump, the same for every colour */\n"
  "float beam(float dy, COLOR c)\n"
  "{\n"
  "    float b = 1.0 - min(dy * dy * bumpInvW * bumpInvW, 1.0);\n"
  "    return b * b * bumpScale;\n"
  "}\n"
  "#else\n"
  "/* a line's light at dy lines from its centre: a Gaussian of area 1, wider for a brighter colour c (as drawn) */\n"
  "float beam(float dy, COLOR c)\n"
  "{\n"
  "    float s = mix(SIGMA_DARK, SIGMA_BRIGHT, max(c.r, max(c.g, c.b)));\n"
  "    float v = s * s + boxVar;\n"
  "    return exp(-dy * dy / (2.0 * v)) * inversesqrt(6.2831853 * v);\n"
  "}\n"
  "#endif\n"
  "\n"
  "#ifdef CRT_FAST_GAMMA\n"
  "#define TO_LINEAR(c) ((c) * (c))\n"
  "#define TO_SCREEN(c) sqrt(c)\n"
  "#else\n"
  "#define TO_LINEAR(c) pow(c, vec3(INPUT_GAMMA))\n"
  "#define TO_SCREEN(c) pow(c, vec3(1.0 / OUTPUT_GAMMA))\n"
  "#endif\n"
  "\n"
  "#ifdef CRT_MASK_TEXTURE\n"
  "/* GLES 3: the host drew the mask below (CRT_FAST_GAMMA's) into a small pattern the mask repeats in, stored\n"
  "   halved, repeated over the screen by the texture unit - one read a pixel, every mask the same cost */\n"
  "uniform sampler2D MaskTexture;\n"
  "uniform vec2 MaskSize;    /* the pattern's place stays highp: a half-float's step at 1920 is 1.5 of its texels */\n"
  "\n"
  "COLOR mask(vec2 pos)\n"
  "{\n"
  "    return texture2D(MaskTexture, pos / MaskSize).rgb * 2.0;\n"
  "}\n"
  "#elif defined(CRT_FAST_GAMMA)\n"
  "COLOR mask(vec2 pos)\n"
  "{\n"
  "#if CRT_MASK == 3\n"
  "    return vec3(1.0);\n"
  "#else\n"
  "    float p = OutputSize.y >= 1600.0 ? 6.0 : OutputSize.y >= 900.0 ? 3.0 : 2.0;\n"
  "    float x = floor(pos.x), y = floor(pos.y);\n"
  "    COLOR m;\n"
  "    /* no mod() and no branch per pixel (p is the same for the whole draw): fract() of the pixel's centre\n"
  "       over a period, (n + 0.5) / p, lands clear of the steps that a float's rounding could move */\n"
  "#if CRT_MASK == 2\n"
  "    /* delta: each row of dots a part of a triad over from the one above */\n"
  "    x += step(0.5, fract((floor(y / max(p / 3.0, 1.0)) + 0.5) * 0.5)) * floor(p / 2.0);\n"
  "#endif\n"
  "    if (p == 2.0) {\n"
  "        /* two pixels: green, then red and blue */\n"
  "        float lit = 2.0 - MASK_DARK;\n"
  "        m = mix(vec3(MASK_DARK, lit, MASK_DARK), vec3(lit, MASK_DARK, lit), step(0.5, fract((x + 0.5) * 0.5)));\n"
  "    } else {\n"
  "        float lit = 3.0 - 2.0 * MASK_DARK;\n"
  "        float i = floor(fract((x + 0.5) / p) * 3.0);    /* 0 1 2: red, green, blue */\n"
  "        vec3 on = vec3(1.0 - step(0.5, i), step(0.5, i) - step(1.5, i), step(1.5, i));\n"
  "        m = MASK_DARK + (lit - MASK_DARK) * on;\n"
  "    }\n"
  "#if CRT_MASK == 1\n"
  "    /* slot: each triad broken by a dark row every slot, the next triad's half a slot lower */\n"
  "    {\n"
  "        float rows = p == 6.0 ? 2.0 : 1.0, slot = 4.0 * rows;\n"
  "        float odd = step(0.5, fract((floor((x + 0.5) / p) + 0.5) * 0.5));\n"
  "        float r = fract((y + odd * slot * 0.5 + 0.5) / slot) * slot;    /* the row in the slot, + 0.5 */\n"
  "        m = mix(vec3(MASK_DARK), m, step(rows, r));\n"
  "        m *= slot / (slot - rows + rows * MASK_DARK);\n"
  "    }\n"
  "#endif\n"
  "    return m;\n"
  "#endif\n"
  "}\n"
  "#else\n"
  "/* the full build keeps the mask code the owner approved on the Pi, as it was */\n"
  "vec3 mask(vec2 pos)\n"
  "{\n"
  "#if CRT_MASK == 3\n"
  "    return vec3(1.0);\n"
  "#else\n"
  "    float p = OutputSize.y >= 1600.0 ? 6.0 : OutputSize.y >= 900.0 ? 3.0 : 2.0;\n"
  "    float x = floor(pos.x), y = floor(pos.y);\n"
  "    vec3 m;\n"
  "#if CRT_MASK == 2\n"
  "    /* delta: each row of dots a part of a triad over from the one above */\n"
  "    x += mod(floor(y / max(p / 3.0, 1.0)), 2.0) * floor(p / 2.0);\n"
  "#endif\n"
  "    if (p == 2.0) {\n"
  "        /* two pixels: green, then red and blue */\n"
  "        float lit = 2.0 - MASK_DARK;\n"
  "        m = mod(x, 2.0) < 1.0 ? vec3(MASK_DARK, lit, MASK_DARK) : vec3(lit, MASK_DARK, lit);\n"
  "    } else {\n"
  "        float lit = 3.0 - 2.0 * MASK_DARK;\n"
  "        float i = floor(mod(x, p) * 3.0 / p);\n"
  "        m = vec3(MASK_DARK);\n"
  "        if (i < 0.5)\n"
  "            m.r = lit;\n"
  "        else if (i < 1.5)\n"
  "            m.g = lit;\n"
  "        else\n"
  "            m.b = lit;\n"
  "    }\n"
  "#if CRT_MASK == 1\n"
  "    /* slot: each triad broken by a dark row every slot, the next triad's half a slot lower */\n"
  "    {\n"
  "        float rows = p == 6.0 ? 2.0 : 1.0, slot = 4.0 * rows;\n"
  "        float t = floor(x / p);\n"
  "        if (mod(y + mod(t, 2.0) * slot * 0.5, slot) < rows)\n"
  "            m = vec3(MASK_DARK);\n"
  "        m *= slot / (slot - rows + rows * MASK_DARK);\n"
  "    }\n"
  "#endif\n"
  "    return m;\n"
  "#endif\n"
  "}\n"
  "#endif\n"
  "\n"
  "void main()\n"
  "{\n"
  "    vec2 p = uv * TextureSize;\n"
  "    float line = floor(p.y - 0.5);    /* the line above the pixel's centre; the one below is line + 1 */\n"
  "    float f = p.y - 0.5 - line;    /* how far below that line's centre, in lines */\n"
  "#ifdef CRT_LITE\n"
  "    float u = uv.x;    /* across: the plain bilinear read */\n"
  "#else\n"
  "    float x = p.x - 0.5;\n"
  "    float fx = clamp((fract(x) - 0.5) * SHARPNESS + 0.5, 0.0, 1.0);\n"
  "    float u = (floor(x) + fx + 0.5) / TextureSize.x;\n"
  "#endif\n"
  "    COLOR e0 = texture2D(Texture, vec2(u, (line + 0.5) / TextureSize.y)).rgb;\n"
  "    COLOR e1 = texture2D(Texture, vec2(u, (line + 1.5) / TextureSize.y)).rgb;\n"
  "    /* no line above the first or below the last: the glass is black there */\n"
  "    COLOR c0 = TO_LINEAR(e0) * step(0.0, line);\n"
  "    COLOR c1 = TO_LINEAR(e1) * step(line + 1.5, TextureSize.y);\n"
  "    /* the width from the colour as the game drew it: a mid grey is a mid-wide beam */\n"
  "    COLOR col = c0 * beam(f, e0) + c1 * beam(1.0 - f, e1);\n"
  "    col *= mask(gl_FragCoord.xy);\n"
  "    gl_FragColor = vec4(TO_SCREEN(clamp(col, 0.0, 1.0)), 1.0);\n"
  "}\n"
  "#endif\n"
  "\n";

static const char ab_glsl_eagle2x[] =
  "// Eagle (2x) - each output quarter takes the corner colour when that corner and its two edge neighbours agree;\n"
  "// the rule pcsx-abnxt's ab_scaler.c eagle2x uses\n"
  "#if defined(VERTEX)\n"
  "attribute vec4 VertexCoord;\n"
  "attribute vec4 TexCoord;\n"
  "varying vec2 uv;\n"
  "uniform mat4 MVPMatrix;\n"
  "void main() { gl_Position = MVPMatrix * VertexCoord; uv = TexCoord.xy; }\n"
  "#elif defined(FRAGMENT)\n"
  "#ifdef GL_ES\n"
  "precision mediump float;\n"
  "#endif\n"
  "varying vec2 uv;\n"
  "uniform sampler2D Texture;\n"
  "uniform vec2 TextureSize;\n"
  "void main() {\n"
  "  vec2 t = 1.0 / TextureSize;\n"
  "  vec2 c = (floor(uv * TextureSize) + 0.5) * t;\n"
  "  vec2 fp = fract(uv * TextureSize);\n"
  "  vec2 dx = vec2(fp.x < 0.5 ? -t.x : t.x, 0.0);\n"
  "  vec2 dy = vec2(0.0, fp.y < 0.5 ? -t.y : t.y);\n"
  "  vec3 E = texture2D(Texture, c).rgb;\n"
  "  vec3 S = texture2D(Texture, c + dx).rgb;       // side neighbour of this quarter\n"
  "  vec3 V = texture2D(Texture, c + dy).rgb;       // vertical neighbour\n"
  "  vec3 K = texture2D(Texture, c + dx + dy).rgb;  // corner\n"
  "  gl_FragColor = vec4((S == V && V == K) ? K : E, 1.0);\n"
  "}\n"
  "#endif\n"
  "\n";

static const char ab_glsl_quilez[] =
  "/*\n"
  "    Fragment shader based on \"Improved texture interpolation\" by Inigo Quilez\n"
  "    Original description: http://www.iquilezles.org/www/articles/texture/texture.htm\n"
  "*/\n"
  "\n"
  "#if defined(VERTEX)\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING out\n"
  "#define COMPAT_ATTRIBUTE in\n"
  "#define COMPAT_TEXTURE texture\n"
  "#else\n"
  "#define COMPAT_VARYING varying \n"
  "#define COMPAT_ATTRIBUTE attribute \n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#define COMPAT_PRECISION mediump\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
  "COMPAT_ATTRIBUTE vec4 COLOR;\n"
  "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
  "COMPAT_VARYING vec4 COL0;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "\n"
  "uniform mat4 MVPMatrix;\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "\n"
  "// vertex compatibility #defines\n"
  "#define vTexCoord TEX0.xy\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "void main()\n"
  "{\n"
  "    gl_Position = MVPMatrix * VertexCoord;\n"
  "    COL0 = COLOR;\n"
  "    TEX0.xy = TexCoord.xy;\n"
  "}\n"
  "\n"
  "#elif defined(FRAGMENT)\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING in\n"
  "#define COMPAT_TEXTURE texture\n"
  "out vec4 FragColor;\n"
  "#else\n"
  "#define COMPAT_VARYING varying\n"
  "#define FragColor gl_FragColor\n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "precision highp float;\n"
  "#else\n"
  "precision mediump float;\n"
  "#endif\n"
  "#define COMPAT_PRECISION mediump\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "uniform sampler2D Texture;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "\n"
  "// fragment compatibility #defines\n"
  "#define Source Texture\n"
  "#define vTexCoord TEX0.xy\n"
  "\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "void main()\n"
  "{\n"
  "    vec2 p = vTexCoord.xy;\n"
  "\n"
  "    p = p * SourceSize.xy + vec2(0.5, 0.5);\n"
  "\n"
  "    vec2 i = floor(p);\n"
  "    vec2 f = p - i;\n"
  "    f = f * f * f * (f * (f * 6.0 - vec2(15.0, 15.0)) + vec2(10.0, 10.0));\n"
  "    p = i + f;\n"
  "\n"
  "    p = (p - vec2(0.5, 0.5)) * SourceSize.zw;\n"
  "\n"
  "    // final sum and weight normalization\n"
  "   FragColor = vec4(COMPAT_TEXTURE(Source, p));\n"
  "} \n"
  "#endif\n"
  "\n";

static const char ab_glsl_scale2x[] =
  "// scale2x (AdvMAME2x) - the same rule as pcsx-abnxt's ab_scaler.c\n"
  "#if defined(VERTEX)\n"
  "attribute vec4 VertexCoord;\n"
  "attribute vec4 TexCoord;\n"
  "varying vec2 uv;\n"
  "uniform mat4 MVPMatrix;\n"
  "void main() { gl_Position = MVPMatrix * VertexCoord; uv = TexCoord.xy; }\n"
  "#elif defined(FRAGMENT)\n"
  "#ifdef GL_ES\n"
  "precision mediump float;\n"
  "#endif\n"
  "varying vec2 uv;\n"
  "uniform sampler2D Texture;\n"
  "uniform vec2 TextureSize;\n"
  "void main() {\n"
  "  vec2 t = 1.0 / TextureSize;\n"
  "  vec2 c = (floor(uv * TextureSize) + 0.5) * t;\n"
  "  vec2 fp = fract(uv * TextureSize);\n"
  "  vec3 E = texture2D(Texture, c).rgb;\n"
  "  vec3 B = texture2D(Texture, c - vec2(0.0, t.y)).rgb;\n"
  "  vec3 H = texture2D(Texture, c + vec2(0.0, t.y)).rgb;\n"
  "  vec3 D = texture2D(Texture, c - vec2(t.x, 0.0)).rgb;\n"
  "  vec3 F = texture2D(Texture, c + vec2(t.x, 0.0)).rgb;\n"
  "  vec3 o = E;\n"
  "  if (B != H && D != F) {\n"
  "    vec3 v = fp.y < 0.5 ? B : H;\n"
  "    vec3 s = fp.x < 0.5 ? D : F;\n"
  "    if (v == s) o = v;\n"
  "  }\n"
  "  gl_FragColor = vec4(o, 1.0);\n"
  "}\n"
  "#endif\n"
  "\n";

static const char ab_glsl_sharp_bilinear_simple[] =
  "/*\n"
  "   Author: rsn8887 (based on TheMaister)\n"
  "   License: Public domain\n"
  "\n"
  "   This is an integer prescale filter that should be combined\n"
  "   with a bilinear hardware filtering (GL_BILINEAR filter or some such) to achieve\n"
  "   a smooth scaling result with minimum blur. This is good for pixelgraphics\n"
  "   that are scaled by non-integer factors.\n"
  "   \n"
  "   The prescale factor and texel coordinates are precalculated\n"
  "   in the vertex shader for speed.\n"
  "*/\n"
  "\n"
  "#if defined(VERTEX)\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING out\n"
  "#define COMPAT_ATTRIBUTE in\n"
  "#define COMPAT_TEXTURE texture\n"
  "#else\n"
  "#define COMPAT_VARYING varying \n"
  "#define COMPAT_ATTRIBUTE attribute \n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#define COMPAT_PRECISION mediump\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
  "COMPAT_ATTRIBUTE vec4 COLOR;\n"
  "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
  "COMPAT_VARYING vec4 COL0;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "\n"
  "uniform mat4 MVPMatrix;\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "\n"
  "// vertex compatibility #defines\n"
  "#define vTexCoord TEX0.xy\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "COMPAT_VARYING vec2 precalc_texel;\n"
  "COMPAT_VARYING vec2 precalc_scale;\n"
  "\n"
  "void main()\n"
  "{\n"
  "    gl_Position = MVPMatrix * VertexCoord;\n"
  "    COL0 = COLOR;\n"
  "    TEX0.xy = TexCoord.xy;\n"
  "\n"
  "    precalc_texel = vTexCoord * SourceSize.xy;\n"
  "    precalc_scale = max(floor(outsize.xy / InputSize.xy), vec2(1.0, 1.0));\n"
  "}\n"
  "\n"
  "#elif defined(FRAGMENT)\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING in\n"
  "#define COMPAT_TEXTURE texture\n"
  "out vec4 FragColor;\n"
  "#else\n"
  "#define COMPAT_VARYING varying\n"
  "#define FragColor gl_FragColor\n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "precision highp float;\n"
  "#else\n"
  "precision mediump float;\n"
  "#endif\n"
  "#define COMPAT_PRECISION mediump\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "uniform sampler2D Texture;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "\n"
  "// fragment compatibility #defines\n"
  "#define Source Texture\n"
  "#define vTexCoord TEX0.xy\n"
  "\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "COMPAT_VARYING vec2 precalc_texel;\n"
  "COMPAT_VARYING vec2 precalc_scale;\n"
  "\n"
  "void main()\n"
  "{\n"
  "   vec2 texel = precalc_texel;\n"
  "   vec2 scale = precalc_scale;\n"
  "\n"
  "   vec2 texel_floored = floor(texel);\n"
  "   vec2 s = fract(texel);\n"
  "   vec2 region_range = 0.5 - 0.5 / scale;\n"
  "\n"
  "   // Figure out where in the texel to sample to get correct pre-scaled bilinear.\n"
  "   // Uses the hardware bilinear interpolator to avoid having to sample 4 times manually.\n"
  "\n"
  "   vec2 center_dist = s - 0.5;\n"
  "   vec2 f = (center_dist - clamp(center_dist, -region_range, region_range)) * scale + 0.5;\n"
  "\n"
  "   vec2 mod_texel = texel_floored + f;\n"
  "\n"
  "   FragColor = vec4(COMPAT_TEXTURE(Source, mod_texel / SourceSize.xy).rgb, 1.0);\n"
  "} \n"
  "#endif\n"
  "\n";

static const char ab_glsl_sharp_bilinear[] =
  "/*\n"
  " * sharp-bilinear\n"
  " * Author: Themaister\n"
  " * License: Public domain\n"
  " * \n"
  " * Does a bilinear stretch, with a preapplied Nx nearest-neighbor scale, giving a\n"
  " * sharper image than plain bilinear.\n"
  " */\n"
  "\n"
  "// Parameter lines go here:\n"
  "#pragma parameter SHARP_BILINEAR_PRE_SCALE \"Sharp Bilinear Prescale\" 4.0 1.0 10.0 1.0\n"
  "#pragma parameter AUTO_PRESCALE \"Automatic Prescale\" 1.0 0.0 1.0 1.0\n"
  "\n"
  "#if defined(VERTEX)\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING out\n"
  "#define COMPAT_ATTRIBUTE in\n"
  "#define COMPAT_TEXTURE texture\n"
  "#else\n"
  "#define COMPAT_VARYING varying \n"
  "#define COMPAT_ATTRIBUTE attribute \n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#define COMPAT_PRECISION mediump\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
  "COMPAT_ATTRIBUTE vec4 COLOR;\n"
  "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
  "COMPAT_VARYING vec4 COL0;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "\n"
  "uniform mat4 MVPMatrix;\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "\n"
  "// vertex compatibility #defines\n"
  "#define vTexCoord TEX0.xy\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "void main()\n"
  "{\n"
  "    gl_Position = MVPMatrix * VertexCoord;\n"
  "    COL0 = COLOR;\n"
  "    TEX0.xy = TexCoord.xy;\n"
  "}\n"
  "\n"
  "#elif defined(FRAGMENT)\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING in\n"
  "#define COMPAT_TEXTURE texture\n"
  "out vec4 FragColor;\n"
  "#else\n"
  "#define COMPAT_VARYING varying\n"
  "#define FragColor gl_FragColor\n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "precision highp float;\n"
  "#else\n"
  "precision mediump float;\n"
  "#endif\n"
  "#define COMPAT_PRECISION mediump\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "uniform sampler2D Texture;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "\n"
  "// fragment compatibility #defines\n"
  "#define Source Texture\n"
  "#define vTexCoord TEX0.xy\n"
  "\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define outsize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "#ifdef PARAMETER_UNIFORM\n"
  "// All parameter floats need to have COMPAT_PRECISION in front of them\n"
  "uniform COMPAT_PRECISION float SHARP_BILINEAR_PRE_SCALE;\n"
  "uniform COMPAT_PRECISION float AUTO_PRESCALE;\n"
  "#else\n"
  "#define SHARP_BILINEAR_PRE_SCALE 4.0\n"
  "#define AUTO_PRESCALE 1.0\n"
  "#endif\n"
  "\n"
  "void main()\n"
  "{\n"
  "   vec2 texel = vTexCoord * SourceSize.xy;\n"
  "   vec2 texel_floored = floor(texel);\n"
  "   vec2 s = fract(texel);\n"
  "   // AutoBleem: at least 1 - a picture larger than the output (a smoothing pass, 2x resolution, a 720p\n"
  "   // screen) gave 0 here, 0.5 / 0 below, and a black screen\n"
  "   float scale = (AUTO_PRESCALE > 0.5) ? max(floor(outsize.y / InputSize.y + 0.01), 1.0) : SHARP_BILINEAR_PRE_SCALE;\n"
  "   float region_range = 0.5 - 0.5 / scale;\n"
  "\n"
  "   // Figure out where in the texel to sample to get correct pre-scaled bilinear.\n"
  "   // Uses the hardware bilinear interpolator to avoid having to sample 4 times manually.\n"
  "\n"
  "   vec2 center_dist = s - 0.5;\n"
  "   vec2 f = (center_dist - clamp(center_dist, -region_range, region_range)) * scale + 0.5;\n"
  "\n"
  "   vec2 mod_texel = texel_floored + f;\n"
  "\n"
  "   FragColor = vec4(COMPAT_TEXTURE(Source, mod_texel / SourceSize.xy).rgb, 1.0);\n"
  "} \n"
  "#endif\n"
  "\n";

static const char ab_glsl_zfast_crt[] =
  "/*\n"
  "    zfast_crt_standard - A simple, fast CRT shader.\n"
  "\n"
  "    Copyright (C) 2017 Greg Hogan (SoltanGris42)\n"
  "\n"
  "    This program is free software; you can redistribute it and/or modify it\n"
  "    under the terms of the GNU General Public License as published by the Free\n"
  "    Software Foundation; either version 2 of the License, or (at your option)\n"
  "    any later version.\n"
  "\n"
  "\n"
  "Notes:  This shader does scaling with a weighted linear filter for adjustable\n"
  "    sharpness on the x and y axes based on the algorithm by Inigo Quilez here:\n"
  "    http://http://www.iquilezles.org/www/articles/texture/texture.htm\n"
  "    but modified to be somewhat sharper.  Then a scanline effect that varies\n"
  "    based on pixel brighness is applied along with a monochrome aperture mask.\n"
  "    This shader runs at 60fps on the Raspberry Pi 3 hardware at 2mpix/s\n"
  "    resolutions (1920x1080 or 1600x1200).\n"
  "*/\n"
  "\n"
  "//For testing compilation \n"
  "//#define FRAGMENT\n"
  "//#define VERTEX\n"
  "\n"
  "//This can't be an option without slowing the shader down\n"
  "//Comment this out for a coarser 3 pixel mask...which is currently broken\n"
  "//on SNES Classic Edition due to Mali 400 gpu precision\n"
  "#define FINEMASK\n"
  "//Some drivers don't return black with texture coordinates out of bounds\n"
  "//SNES Classic is too slow to black these areas out when using fullscreen\n"
  "//overlays.  But you can uncomment the below to black them out if necessary\n"
  "//#define BLACK_OUT_BORDER\n"
  "\n"
  "// Parameter lines go here:\n"
  "#pragma parameter BLURSCALEX \"Blur Amount X-Axis\" 0.30 0.0 1.0 0.05\n"
  "#pragma parameter LOWLUMSCAN \"Scanline Darkness - Low\" 6.0 0.0 10.0 0.5\n"
  "#pragma parameter HILUMSCAN \"Scanline Darkness - High\" 8.0 0.0 50.0 1.0\n"
  "#pragma parameter BRIGHTBOOST \"Dark Pixel Brightness Boost\" 1.25 0.5 1.5 0.05\n"
  "#pragma parameter MASK_DARK \"Mask Effect Amount\" 0.25 0.0 1.0 0.05\n"
  "#pragma parameter MASK_FADE \"Mask/Scanline Fade\" 0.8 0.0 1.0 0.05\n"
  "\n"
  "#if defined(VERTEX)\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING out\n"
  "#define COMPAT_ATTRIBUTE in\n"
  "#define COMPAT_TEXTURE texture\n"
  "#else\n"
  "#define COMPAT_VARYING varying \n"
  "#define COMPAT_ATTRIBUTE attribute \n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "#ifdef GL_ES\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "#define COMPAT_PRECISION highp\n"
  "#else\n"
  "#define COMPAT_PRECISION mediump\n"
  "#endif\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "COMPAT_ATTRIBUTE vec4 VertexCoord;\n"
  "COMPAT_ATTRIBUTE vec4 COLOR;\n"
  "COMPAT_ATTRIBUTE vec4 TexCoord;\n"
  "COMPAT_VARYING vec4 COL0;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "COMPAT_VARYING float maskFade;\n"
  "COMPAT_VARYING vec2 invDims;\n"
  "COMPAT_VARYING vec2 lineAA;\n"
  "\n"
  "vec4 _oPosition1;\n"
  "uniform mat4 MVPMatrix;\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "\n"
  "// compatibility #defines\n"
  "#define vTexCoord TEX0.xy\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define OutSize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "#ifdef PARAMETER_UNIFORM\n"
  "// All parameter floats need to have COMPAT_PRECISION in front of them\n"
  "uniform COMPAT_PRECISION float BLURSCALEX;\n"
  "//uniform COMPAT_PRECISION float BLURSCALEY;\n"
  "uniform COMPAT_PRECISION float LOWLUMSCAN;\n"
  "uniform COMPAT_PRECISION float HILUMSCAN;\n"
  "uniform COMPAT_PRECISION float BRIGHTBOOST;\n"
  "uniform COMPAT_PRECISION float MASK_DARK;\n"
  "uniform COMPAT_PRECISION float MASK_FADE;\n"
  "#else\n"
  "#define BLURSCALEX 0.45\n"
  "//#define BLURSCALEY 0.20\n"
  "#define LOWLUMSCAN 5.0\n"
  "#define HILUMSCAN 10.0\n"
  "#define BRIGHTBOOST 1.25\n"
  "#define MASK_DARK 0.25\n"
  "#define MASK_FADE 0.8\n"
  "#endif\n"
  "\n"
  "void main()\n"
  "{\n"
  "    gl_Position = MVPMatrix * VertexCoord;\n"
  "    \n"
  "    TEX0.xy = TexCoord.xy*1.0001;\n"
  "    maskFade = 0.3333*MASK_FADE;\n"
  "    invDims = 1.0/TextureSize.xy;\n"
  "    // AutoBleem: x = how far a line's height on the screen is from a whole number of pixels - 0 at 720p\n"
  "    // (3 px) or 4K (9 px), 1 at 1080p (4.5 px); y = a third of a screen pixel in lines. Where x > 0 the\n"
  "    // scanline is averaged over the pixel (three samples, as crt-pi's MULTISAMPLE) and drawn a little\n"
  "    // softer, so lines of 4 and 5 pixels do not show as a pattern; a whole scale draws as before.\n"
  "    lineAA.x = 1.0 - abs(2.0 * fract(OutputSize.y / InputSize.y) - 1.0);\n"
  "    lineAA.y = (InputSize.y / OutputSize.y) / 3.0;\n"
  "}\n"
  "\n"
  "#elif defined(FRAGMENT)\n"
  "\n"
  "#ifdef GL_ES\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "precision highp float;\n"
  "#else\n"
  "precision mediump float;\n"
  "#endif\n"
  "#ifdef GL_FRAGMENT_PRECISION_HIGH\n"
  "#define COMPAT_PRECISION highp\n"
  "#else \n"
  "#define COMPAT_PRECISION mediump\n"
  "#endif\n"
  "#else\n"
  "#define COMPAT_PRECISION\n"
  "#endif\n"
  "\n"
  "#if __VERSION__ >= 130\n"
  "#define COMPAT_VARYING in\n"
  "#define COMPAT_TEXTURE texture\n"
  "out COMPAT_PRECISION vec4 FragColor;\n"
  "#else\n"
  "#define COMPAT_VARYING varying\n"
  "#define FragColor gl_FragColor\n"
  "#define COMPAT_TEXTURE texture2D\n"
  "#endif\n"
  "\n"
  "uniform COMPAT_PRECISION int FrameDirection;\n"
  "uniform COMPAT_PRECISION int FrameCount;\n"
  "uniform COMPAT_PRECISION vec2 OutputSize;\n"
  "uniform COMPAT_PRECISION vec2 TextureSize;\n"
  "uniform COMPAT_PRECISION vec2 InputSize;\n"
  "uniform sampler2D Texture;\n"
  "COMPAT_VARYING vec4 TEX0;\n"
  "COMPAT_VARYING float maskFade;\n"
  "COMPAT_VARYING vec2 invDims;\n"
  "COMPAT_VARYING vec2 lineAA;\n"
  "\n"
  "// compatibility #defines\n"
  "#define Source Texture\n"
  "#define vTexCoord TEX0.xy\n"
  "#define texture(c, d) COMPAT_TEXTURE(c, d)\n"
  "#define SourceSize vec4(TextureSize, 1.0 / TextureSize) //either TextureSize or InputSize\n"
  "#define OutSize vec4(OutputSize, 1.0 / OutputSize)\n"
  "\n"
  "#ifdef PARAMETER_UNIFORM\n"
  "// All parameter floats need to have COMPAT_PRECISION in front of them\n"
  "uniform COMPAT_PRECISION float BLURSCALEX;\n"
  "//uniform COMPAT_PRECISION float BLURSCALEY;\n"
  "uniform COMPAT_PRECISION float LOWLUMSCAN;\n"
  "uniform COMPAT_PRECISION float HILUMSCAN;\n"
  "uniform COMPAT_PRECISION float BRIGHTBOOST;\n"
  "uniform COMPAT_PRECISION float MASK_DARK;\n"
  "uniform COMPAT_PRECISION float MASK_FADE;\n"
  "#else\n"
  "#define BLURSCALEX 0.45\n"
  "//#define BLURSCALEY 0.20\n"
  "#define LOWLUMSCAN 5.0\n"
  "#define HILUMSCAN 10.0\n"
  "#define BRIGHTBOOST 1.25\n"
  "#define MASK_DARK 0.25\n"
  "#define MASK_FADE 0.8\n"
  "#endif\n"
  "\n"
  "void main()\n"
  "{\n"
  "\n"
  "    //This is just like \"Quilez Scaling\" but sharper\n"
  "    COMPAT_PRECISION vec2 p = vTexCoord * TextureSize;\n"
  "    COMPAT_PRECISION vec2 i = floor(p) + 0.50;\n"
  "    COMPAT_PRECISION vec2 f = p - i;\n"
  "    p = (i + 4.0*f*f*f)*invDims;\n"
  "    p.x = mix( p.x , vTexCoord.x, BLURSCALEX);\n"
  "#define ratio SourceSize.x/InputSize.x    \n"
  "#if defined(FINEMASK) \n"
  "    COMPAT_PRECISION float whichmask = floor(vTexCoord.x*OutputSize.x*ratio)*-0.5;\n"
  "    COMPAT_PRECISION float mask = 1.0 + float(fract(whichmask) < 0.5) * -MASK_DARK;\n"
  "#else\n"
  "    COMPAT_PRECISION float whichmask = floor(vTexCoord.x*OutputSize.x*ratio)*-0.3333;\n"
  "    COMPAT_PRECISION float mask = 1.0 + float(fract(whichmask) < 0.3333) * -MASK_DARK;\n"
  "#endif\n"
  "    COMPAT_PRECISION vec3 colour = COMPAT_TEXTURE(Source, p).rgb;\n"
  "    \n"
  "    // AutoBleem: the scanline at three points of the pixel (all three at f.y on a whole scale: as before)\n"
  "    COMPAT_PRECISION float soften = 1.0 - 0.25 * lineAA.x;\n"
  "    COMPAT_PRECISION float scanLineWeight = 0.0;\n"
  "    COMPAT_PRECISION float scanLineWeightB = 0.0;\n"
  "    for (int k = -1; k <= 1; k++) {\n"
  "        COMPAT_PRECISION float fy = fract(f.y + 0.5 + float(k) * lineAA.y * lineAA.x) - 0.5;\n"
  "        COMPAT_PRECISION float Y = fy*fy;\n"
  "        COMPAT_PRECISION float YY = Y*Y;\n"
  "        scanLineWeight += (BRIGHTBOOST - LOWLUMSCAN*soften*(Y - 2.05*YY));\n"
  "        scanLineWeightB += 1.0 - HILUMSCAN*soften*(YY-2.8*YY*Y);\n"
  "    }\n"
  "    scanLineWeight *= 0.3333333;\n"
  "    scanLineWeightB *= 0.3333333;\n"
  "    \n"
  "#if defined(BLACK_OUT_BORDER)\n"
  "    colour.rgb*=float(tc.x > 0.0)*float(tc.y > 0.0); //why doesn't the driver do the right thing?\n"
  "#endif\n"
  "\n"
  "    FragColor.rgba = vec4(colour.rgb*mix(scanLineWeight*mask, scanLineWeightB, dot(colour.rgb,vec3(maskFade))),1.0);\n"
  "    \n"
  "} \n"
  "#endif\n"
  "\n";
